import pandas as pd

# Load the data from the Excel file
df = pd.read_excel('data.xlsx')

# Extract the rider names and split them into individual words
rider_names = df['Rider'].str.split()

# Create a dictionary to store the count of each country
country_counts = {}

# Iterate over the rider names and update the count for each country
for name in rider_names:
    for word in name:
        if word.isalpha():
            if word in country_counts:
                country_counts[word] += 1
            else:
                country_counts[word] = 1

# Find the country with the most riders
most_riders_country = max(country_counts, key=country_counts.get)

print(most_riders_country)

